import{_ as t,o as a,c as r,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Karnavedha source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/19-karnavedha-profile.md","filePath":"reference/19-karnavedha-profile.md","lastUpdated":1788414836000}'),d={name:"reference/19-karnavedha-profile.md"};function n(i,e,s,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="karnavedha-source-profile" tabindex="-1">Karnavedha source profile <a class="header-anchor" href="#karnavedha-source-profile" aria-label="Permalink to &quot;Karnavedha source profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The configured ear-piercing profile is based on B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter VIII, “Post-natal ceremonies” / “Ear boring (Karnavedha),” printed page 22 (PDF page 26). Its reference to Tithis “usually declared as inauspicious” is resolved through Chapter V&#39;s general Panchanga Suddhi list, printed page 11 (PDF page 15):</p><p><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf</a></p><p>Raman is a modern synthesis and secondary authority, not primary scripture. The profile screens electional time; medical safety, consent, sterile technique and aftercare remain matters for qualified practitioners and guardians.</p><h2 id="rule-to-code-crosswalk" tabindex="-1">Rule-to-code crosswalk <a class="header-anchor" href="#rule-to-code-crosswalk" aria-label="Permalink to &quot;Rule-to-code crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Implementation</th><th>Treatment</th></tr></thead><tbody><tr><td>Perform on the 12th or 16th day after birth, or in the 6th, 7th or 8th month</td><td><code>manual_checks</code></td><td>Child age is not an input and is disclosed on every candidate.</td></tr><tr><td>Use forenoon or afternoon, never night</td><td><code>daytime_only</code></td><td><code>night_slots</code> returns no candidates even when MCP requests <code>include_night</code>. The website is already daytime-only.</td></tr><tr><td>Reject a day ruled by two Nakshatras or two Tithis</td><td><code>manual_checks</code></td><td>The relevant ceremony interval is not supplied, so transition counting is not inferred.</td></tr><tr><td>Reject generally inauspicious Tithis</td><td><code>avoid_tithi_numbers</code></td><td>Cross-referenced to Chapter V: 4th, 6th, 8th, 12th, 14th, Purnima and Amavasya; both terminal Tithis map to 15.</td></tr><tr><td>Monday, Wednesday, Thursday and Friday are good</td><td><code>allowed_varas</code></td><td>Other weekdays reject the day.</td></tr><tr><td>Reject Kumbha, Simha and Vrischika rising</td><td><code>allowed_lagnas</code></td><td>The other nine Rasis are admitted at slot time.</td></tr><tr><td>Leave the 8th house unoccupied</td><td><code>manual_checks</code></td><td>Full election-chart occupancy remains practitioner-reviewed.</td></tr></tbody></table><h2 id="product-contract-and-limitations" tabindex="-1">Product contract and limitations <a class="header-anchor" href="#product-contract-and-limitations" aria-label="Permalink to &quot;Product contract and limitations&quot;">​</a></h2><p>The existing samskara exclusions, hard avoid windows, Tithi-family ranking, personal scoring and relative tiers remain shared project rules not established by this citation. MCP exposes <code>muhurta.karnavedha</code>, the daytime-only constraint and every manual check; the browser receives the same generated contract.</p>',9)])])}const m=t(d,[["render",n]]);export{p as __pageData,m as default};
